const CW = 'https://appcadabra-chatwoot.jmyxxj.easypanel.host';
const ACC = '2';
const INBOX = 1;
const TOKEN = '8vCuVj2MnkufoQCuS4gmWXVr';
const H = { 'api_access_token': TOKEN, 'Content-Type': 'application/json' };
const b = $input.first().json.body || {};
const wa = String(b.wa_id || '').replace(/[^0-9]/g,'');
if (!wa) return [{ json: { ok:false, motivo:'sin wa_id' } }];
const nombre = b.nombre || ('Cliente ' + wa);
const msgCliente = b.mensaje_cliente || '';
const msgBot = b.respuesta_bot || '';

// Helper HTTP con el cliente de n8n (fetch no existe en Code node)
const req = async (method, url, body) => {
  try {
    const opt = { method, url, headers: H, json: true };
    if (body) opt.body = body;
    const d = await this.helpers.httpRequest(opt);
    return d;
  } catch (e) { return (e.response && e.response.body) ? e.response.body : { __err: String(e.message||e) }; }
};

// 1) Buscar contacto por identifier (wa)
let contactId=null, sourceId=null;
const s = await req('GET', `${CW}/api/v1/accounts/${ACC}/contacts/search?q=${wa}`);
if (s && s.payload && s.payload.length) {
  const c = s.payload.find(x => x.identifier===wa || (x.phone_number||'').includes(wa)) || s.payload[0];
  contactId = c.id;
  const ci = await req('GET', `${CW}/api/v1/accounts/${ACC}/contacts/${contactId}`);
  const inboxes = (ci && ci.payload && ci.payload.contact_inboxes) || [];
  const mine = inboxes.find(x => x.inbox && x.inbox.id===INBOX);
  sourceId = mine ? mine.source_id : null;
}
// 2) Crear contacto si no existe
if (!contactId) {
  const cr = await req('POST', `${CW}/api/v1/accounts/${ACC}/contacts`, { inbox_id: INBOX, name: nombre, phone_number: '+'+wa, identifier: wa });
  contactId = cr && cr.payload && cr.payload.contact && cr.payload.contact.id;
  sourceId = cr && cr.payload && cr.payload.contact_inbox && cr.payload.contact_inbox.source_id;
}
// 3) Si no tengo source_id aún, crear el contact_inbox
if (contactId && !sourceId) {
  const cib = await req('POST', `${CW}/api/v1/accounts/${ACC}/contacts/${contactId}/contact_inboxes`, { inbox_id: INBOX });
  sourceId = cib && cib.source_id;
}
// 4) Buscar conversación abierta del contacto, o crear una
let convId=null;
const cv = await req('GET', `${CW}/api/v1/accounts/${ACC}/contacts/${contactId}/conversations`);
const convs = (cv && cv.payload) || [];
const abierta = convs.find(x => x.status==='open' || x.status==='pending') || convs[0];
if (abierta) convId = abierta.id;
if (!convId) {
  const nc = await req('POST', `${CW}/api/v1/accounts/${ACC}/conversations`, { source_id: sourceId, inbox_id: INBOX, contact_id: contactId });
  convId = nc && nc.id;
}
if (!convId) return [{ json: { ok:false, motivo:'sin conversacion', contactId, sourceId } }];
// 5) Push mensajes: cliente (incoming) y bot (outgoing).
//    Marcamos con content_attributes.espejo=true para que el webhook los IGNORE
//    (si no, el reenvío vendedor→WhatsApp entraría en bucle con nuestros propios mensajes).
if (msgCliente) await req('POST', `${CW}/api/v1/accounts/${ACC}/conversations/${convId}/messages`, { content: msgCliente, message_type: 'incoming', content_attributes: { espejo: true } });
if (msgBot) await req('POST', `${CW}/api/v1/accounts/${ACC}/conversations/${convId}/messages`, { content: msgBot, message_type: 'outgoing', content_attributes: { espejo: true } });
return [{ json: { ok:true, contactId, convId } }];
